import { renderHomePage, renderBouquetGrid, filterBouquets, sortBouquets, selectBouquetSize, formatGbp, renderDeliveryZones } from "./render-home-page.ts";
type BouquetSize = 'Small' | 'Classic' | 'Grand';

type DeliveryZone = {
  name: string;
  prefixes: string[];
  fee: number;
  cutoffHour: number;
  cutoffMinute: number;
};

type SameDayResult =
  | { status: 'eligible'; postcode: string; zone: string; fee: number; feeGbp: string; cutoffTime: string; message: string }
  | { status: 'not-eligible'; postcode: string; zone: string; fee: number; feeGbp: string; cutoffTime: string; message: string }
  | { status: 'not-served'; postcode: string; message: string }
  | { status: 'invalid'; postcode: string; message: string };

type Occasion =
  | 'Birthday'
  | 'Anniversary'
  | 'New Baby'
  | 'Sympathy'
  | 'Thank You';

type Bouquet = {
  id: string;
  name: string;
  price: number;
  sizePrices?: Partial<Record<BouquetSize, number>>;
  palette?: string[];
  flowers?: string[];
  occasions?: Occasion[];
};

type OccasionSection = {
  occasion: Occasion;
  note: string;
  bouquets: Bouquet[];
};

