  sections: OccasionSection[];
};

type EnquiryForm = {
  senderName: string;
  recipientName: string;
  deliveryPostcode: string;
  deliveryDate: string;
  budgetRange: string;
  occasion: string;
  cardMessage: string;
};

type EnquiryConfirmation = {
  reference: string;
  ok: boolean;
  errors: Record<string, string>;
  message: string;
};

const WILDSTEM_OCCASIONS: Occasion[] = ['Birthday', 'Anniversary', 'New Baby', 'Sympathy', 'Thank You'];

const WILDSTEM_ETIQUETTE: Record<Occasion, string> = {
  Birthday: 'Bright, cheerful stems are welcome. Avoid lilies if pets are in the home.',
  Anniversary: 'Classic roses or peonies suit the occasion. Keep the palette romantic and tonal.',
  'New Baby': 'Soft pastels and no strong scent. Skip lilies around a newborn household.',
  Sympathy: 'No bright reds. Choose whites, greens and soft creams, and keep the card brief and kind.',
  'Thank You': 'A modest, warm mix works well. Mixed seasonal stems feel personal without being lavish.'
};

const WILDSTEM_CARD_MESSAGE_LIMIT = 250;

/**
 * Matches a postcode to a served delivery zone.
 * req-5, req-6
 */
function matchDeliveryZone(postcode: string): DeliveryZone | null {
  if (typeof postcode !== 'string') {
    return null;
  }
  const normalised = postcode.toUpperCase().replace(/\s+/g, '');
  if (normalised.length === 0) {
    return null;
  }
  const zones: DeliveryZone[] = [
    { name: 'Central', prefixes: ['EC', 'WC', 'N1'], fee: 4.5, cutoffHour: 13, cutoffMinute: 0 },
    { name: 'North', prefixes: ['N', 'NW'], fee: 5.5, cutoffHour: 12, cutoffMinute: 30 },
    { name: 'East', prefixes: ['E', 'IG'], fee: 6, cutoffHour: 12, cutoffMinute: 0 },
    { name: 'South', prefixes: ['SE', 'SW'], fee: 6.5, cutoffHour: 11, cutoffMinute: 30 },
    { name: 'West', prefixes: ['W', 'TW'], fee: 7, cutoffHour: 11, cutoffMinute: 0 }
  ];
  let best: DeliveryZone | null = null;
  let bestLength = -1;
  for (let i = 0; i < zones.length; i += 1) {
    const zone = zones[i];
    for (let j = 0; j < zone.prefixes.length; j += 1) {
      const prefix = zone.prefixes[j];
      if (normalised.indexOf(prefix) === 0 && prefix.length > bestLength) {
        best = zone;
        bestLength = prefix.length;
      }
    }
  }
  return best;
}

/**
 * Formats a number as GBP with exactly two decimal places.
 * req-11
 */
function formatWildstemGbp(amount: number): string {
  const safe = typeof amount === 'number' && Number.isFinite(amount) ? amount : 0;
  return '£' + safe.toFixed(2);
}

/**
 * Checks whether same-day delivery is still possible for a postcode at a given time.
 * req-6
 */
function checkSameDayEligibility(postcode: string, currentTime: Date): SameDayResult {
  if (typeof postcode !== 'string' || postcode.trim().length === 0) {
    return { status: 'invalid', postcode: typeof postcode === 'string' ? postcode : '', message: 'Please enter a postcode.' };
  }
  const zone = matchDeliveryZone(postcode);
  if (zone === null) {
    return {
      status: 'not-served',
      postcode: postcode,
      message: 'This postcode is outside our served zones, so we cannot offer same-day delivery or quote a fee.'
    };
  }
  const cutoff = 'by ' + String(zone.cutoffHour).padStart(2, '0') + ':' + String(zone.cutoffMinute).padStart(2, '0');
  const feeGbp = formatWildstemGbp(zone.fee);
  const now = currentTime instanceof Date ? currentTime : new Date(NaN);
  const currentMinutes = now.getHours() * 60 + now.getMinutes();
  const cutoffMinutes = zone.cutoffHour * 60 + zone.cutoffMinute;
  if (Number.isFinite(currentMinutes) && currentMinutes <= cutoffMinutes) {
    return {
      status: 'eligible',
      postcode: postcode,
      zone: zone.name,
      fee: zone.fee,
      feeGbp: feeGbp,
      cutoffTime: cutoff,
      message: 'Same-day delivery is available for ' + zone.name + ' at ' + feeGbp + ' if ordered ' + cutoff + '.'
    };
  }
  return {
    status: 'not-eligible',
    postcode: postcode,
    zone: zone.name,
    fee: zone.fee,
    feeGbp: feeGbp,
    cutoffTime: cutoff,
    message: 'Same-day delivery for ' + zone.name + ' closed at ' + cutoff + '. The delivery fee is ' + feeGbp + ' for the next available day.'
  };
}

/**
 * Builds the occasions page sections with recommended bouquets and etiquette notes.
 * req-7
 */
function renderOccasionSections(occasions: Occasion[], bouquets: Bouquet[]): OccasionSectionsProps {
  const occasionList = Array.isArray(occasions) && occasions.length > 0 ? occasions : WILDSTEM_OCCASIONS;
  const bouquetList = Array.isArray(bouquets) ? bouquets : [];
  const sections: OccasionSection[] = [];
  for (let i = 0; i < occasionList.length; i += 1) {
    const occasion = occasionList[i];
    const note = Object.prototype.hasOwnProperty.call(WILDSTEM_ETIQUETTE, occasion)
      ? WILDSTEM_ETIQUETTE[occasion]
      : 'Choose a palette that suits the recipient and keep the card message warm and brief.';
    const recommended: Bouquet[] = [];
    for (let j = 0; j < bouquetList.length; j += 1) {
      const bouquet = bouquetList[j];
      const tags = Array.isArray(bouquet.occasions) ? bouquet.occasions : [];
      if (tags.indexOf(occasion) !== -1) {
        recommended.push(bouquet);
      }
    }
    sections.push({ occasion: occasion, note: note, bouquets: recommended });
  }
  return { sections: sections };
}

/**
 * Counts the characters in a card message.
 * req-8
 */
function countCardMessage(message: string): number {
  if (typeof message !== 'string') {
    return 0;
  }
  return message.length;
}

/**
 * Generates a deterministic enquiry reference.
 * req-9
 */
function generateEnquiryReference(): string {
  const stamp = Date.now().toString(36).toUpperCase();
  let hash = 0;
  const seed = 'wildstem-' + stamp;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 2176782336;
  }
  const suffix = hash.toString(36).toUpperCase().padStart(6, '0');
  return 'WS-' + stamp + '-' + suffix;
}

/**
 * Validates and submits a bespoke enquiry, returning errors or a confirmation reference.
 * req-4, req-8, req-9, req-10
 */
async function submitEnquiry(form: EnquiryForm, size: BouquetSize): Promise<EnquiryConfirmation> {
  const errors: Record<string, string> = {};
  const senderName = typeof form.senderName === 'string' ? form.senderName.trim() : '';
  const recipientName = typeof form.recipientName === 'string' ? form.recipientName.trim() : '';
  const deliveryPostcode = typeof form.deliveryPostcode === 'string' ? form.deliveryPostcode.trim() : '';
  const deliveryDate = typeof form.deliveryDate === 'string' ? form.deliveryDate.trim() : '';
  const budgetRange = typeof form.budgetRange === 'string' ? form.budgetRange.trim() : '';
  const occasion = typeof form.occasion === 'string' ? form.occasion.trim() : '';
  const cardMessage = typeof form.cardMessage === 'string' ? form.cardMessage : '';
  const chosenSize: BouquetSize = size === 'Small' || size === 'Classic' || size === 'Grand' ? size : 'Classic';
  if (senderName.length === 0) {
    errors.senderName = 'Please enter your name.';
  }
  if (recipientName.length === 0) {
    errors.recipientName = 'Please enter the recipient name.';
  }
  if (deliveryPostcode.length === 0) {
    errors.deliveryPostcode = 'Please enter a delivery postcode.';
  } else if (matchDeliveryZone(deliveryPostcode) === null) {
    errors.deliveryPostcode = 'This postcode is outside our served zones.';
  }
  if (deliveryDate.length === 0) {
    errors.deliveryDate = 'Please choose a delivery date.';
  } else {
    const parsed = new Date(deliveryDate + 'T00:00:00');
    if (!Number.isFinite(parsed.getTime())) {
      errors.deliveryDate = 'Please choose a valid delivery date.';
    } else {
      const today = new Date();
      const todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate());
      if (parsed.getTime() <= todayStart.getTime()) {
        errors.deliveryDate = 'The delivery date must be in the future.';
      }
    }
  }
  if (budgetRange.length === 0) {
    errors.budgetRange = 'Please choose a budget range.';
  }
  if (occasion.length === 0) {
    errors.occasion = 'Please choose an occasion.';
  }
  if (countCardMessage(cardMessage) > WILDSTEM_CARD_MESSAGE_LIMIT) {
    errors.cardMessage = 'The card message must be 250 characters or fewer.';
  }
  const errorKeys = Object.keys(errors);
  if (errorKeys.length > 0) {
    return { reference: '', ok: false, errors: errors, message: 'Please correct the highlighted fields.' };
  }
  const reference = generateEnquiryReference();
  return {
    reference: reference,
    ok: true,
    errors: {},
    message: 'Thank you, ' + senderName + '. Your ' + chosenSize + ' ' + occasion + ' enquiry for ' + recipientName + ' is confirmed. Reference ' + reference + '.'
  };
}
