type ServeStatus = 'queued' | 'running' | 'succeeded' | 'failed';

interface ServeCommand {
  id: string;
  target: string;
  variant?: string;
  attempts?: number;
  at?: string;
}

interface Page {
  id: string;
  status: ServeStatus;
  updatedAt: string;
  target: string;
  variant: string;
  path: string;
}

interface ServeRun {
  id: string;
  status: ServeStatus;
  updatedAt: string;
  target: string;
  variant: string;
}

const serveRunStore: ServeRun[] = [];

/**
 * Derives a deterministic page id from a serve command.
 *
 * @param command - the serve command producing the page.
 * @returns a stable identifier for the served page.
 */
function derivePageId(command: ServeCommand): string {
  const seed = String(command.id) + '|' + String(command.target) + '|' + String(command.variant === undefined ? 'default' : command.variant);
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i = i + 1) {
    hash = hash ^ seed.charCodeAt(i);
    hash = (hash * 16777619) >>> 0;
  }
  return 'page-' + hash.toString(16).padStart(8, '0');
}

/**
 * Derives a deterministic serve run id from a serve command.
 *
 * @param command - the serve command producing the run record.
 * @returns a stable identifier for the serve run.
 */
function deriveServeRunId(command: ServeCommand): string {
  const seed = String(command.id) + '::run::' + String(command.target);
  let hash = 5381;
  for (let i = 0; i < seed.length; i = i + 1) {
    hash = ((hash << 5) + hash + seed.charCodeAt(i)) >>> 0;
  }
  return 'serve-' + hash.toString(16).padStart(8, '0');
}

/**
 * Normalizes a serve command into a fully-populated value with stable defaults.
 *
 * @param command - the incoming serve command.
 * @returns the normalized command fields used to build a page.
 */
function normalizeServeCommand(command: ServeCommand): { id: string; target: string; variant: string; attempts: number; at: string } {
  const variant = command.variant === undefined || command.variant.trim() === '' ? 'default' : command.variant.trim();
  const attempts = command.attempts === undefined ? 1 : command.attempts;
  const at = command.at === undefined || command.at.trim() === '' ? '1970-01-01T00:00:00.000Z' : command.at;
  return {
    id: String(command.id).trim(),
    target: String(command.target).trim(),
    variant: variant,
    attempts: attempts,
    at: at
  };
}

/**
 * Serves a page for the given command and records the resulting serve run.
 *
 * @param command - the serve command describing the page to render.
 * @returns a Promise resolving to the served page.
 */
async function runServe(command: ServeCommand): Promise<Page> { // req-1
  const normalized = normalizeServeCommand(command);
  const pageId = derivePageId(command);
  const runId = deriveServeRunId(command);
  const path = '/' + normalized.target + (normalized.variant === 'default' ? '' : '/' + normalized.variant);
  const failed = normalized.target === '';
  const status: ServeStatus = failed ? 'failed' : 'succeeded';
  const page: Page = {
    id: pageId,
    status: status,
    updatedAt: normalized.at,
    target: normalized.target,
    variant: normalized.variant,
    path: path
  };
  const run: ServeRun = {
    id: runId,
    status: status,
    updatedAt: normalized.at,
    target: normalized.target,
    variant: normalized.variant
  };
  serveRunStore.unshift(run);
  return page;
}

/**
 * Lists previously recorded serve runs, most recent first.
 *
 * @param id - identifier used to filter serve runs by target id.
 * @param limit - optional maximum number of runs to return.
 * @returns a Promise resolving to the matching serve runs.
 */
async function listServeRuns(id: string, limit?: number): Promise<ServeRun[]> { // req-2
  const needle = String(id).trim();
