import { renderHomePage, renderBouquetGrid, filterBouquets, sortBouquets, selectBouquetSize, formatGbp, renderDeliveryZones } from "../generated/render-home-page.ts";
import { checkSameDayEligibility, matchDeliveryZone, renderOccasionSections, submitEnquiry, generateEnquiryReference } from "../generated/check-same-day-eligibility.ts";
import { runWebMarketing, listWebMarketingRuns } from "../domain/web-marketing.ts";
// req-7 — show runner read model for the Wildstem marketing site.

type ShowRunStatus = 'queued' | 'running' | 'succeeded' | 'failed' | 'cancelled';

interface ShowCommand {
  id: string;
  status?: string;
  updatedAt?: string;
  idempotencyKey?: string;
  payload?: Record<string, unknown>;
}

interface ShowRun {
  id: string;
  status: ShowRunStatus;
  updatedAt: string;
  detail: string;
  payload: Record<string, unknown>;
}

interface ClientRecord {
  id: string;
  status: string;
  updatedAt: string;
  reference: string;
  runs: ShowRun[];
}

const WILDMARKETING_SHOW_STORE: Record<string, ClientRecord> = {};

function coerceText(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function hashText(input: string): string {
  let h = 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    h ^= input.charCodeAt(i);
    h = (h * 16777619) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

function normalizeShowStatus(value: unknown): ShowRunStatus {
  const text = coerceText(value).toLowerCase();
  if (text === 'queued' || text === 'running' || text === 'succeeded' || text === 'failed' || text === 'cancelled') {
    return text;
  }
  return 'succeeded';
}

function shardShowReference(id: string, status: string): string {
  return 'WS-' + hashText(id + '|' + status).toUpperCase();
}

/**
 * Runs the show operation for a single ShowCommand and returns the persisted Client
 * record, creating the record on first call and refreshing it on repeat calls with the
 * same id so duplicate submissions still yield a stable reference.
 * // req-7
 * @param command the show command carrying the client id, status and payload.
 * @returns the Client record for the command's id.
 */
async function runShow(command: ShowCommand): Promise<ClientRecord> {
  const id = coerceText(command && command.id).trim();
  const status = normalizeShowStatus(command && command.status);
  const updatedAt = coerceText(command && command.updatedAt) || '1970-01-01T00:00:00.000Z';
  const payload = (command && typeof command.payload === 'object' && command.payload !== null)
    ? command.payload
    : {};
  const existing = WILDMARKETING_SHOW_STORE[id];
  const run: ShowRun = {
    id: id,
    status: status,
    updatedAt: updatedAt,
    detail: 'show ' + status + ' for ' + (id === '' ? 'unidentified' : id),
    payload: payload,
  };
  if (existing) {
    existing.status = status;
    existing.updatedAt = updatedAt;
    existing.runs.push(run);
    return existing;
  }
  const record: ClientRecord = {
    id: id,
    status: status,
    updatedAt: updatedAt,
    reference: shardShowReference(id, status),
    runs: [run],
  };
  WILDMARKETING_SHOW_STORE[id] = record;
  return record;
}

/**
 * Lists the recorded show runs for a given client id in the order they were recorded,
 * honouring an optional limit that bounds the number of returned runs.
 * // req-7
 * @param id the client id whose runs are requested.
 * @param limit optional maximum number of runs to return.
 * @returns the recorded show runs, most recent last.
 */
async function listShowRuns(id: string, limit?: number): Promise<ShowRun[]> {
  const key = coerceText(id).trim();
  const record = WILDMARKETING_SHOW_STORE[key];
  if (!record) {
    return [];
  }
  const runs = record.runs.slice();
  if (typeof limit === 'number' && isFinite(limit) && limit >= 0) {
    return runs.slice(0, Math.floor(limit));
  }
  return runs;
}
