import { runServe, listServeRuns } from "./serve.ts";
type EntityStatus = 'draft' | 'active' | 'published' | 'archived';

interface TrackRun {
  id: string;
  status: EntityStatus;
  updatedAt: string;
}

interface Card {
  id: string;
  status: EntityStatus;
  updatedAt: string;
}

interface TrackCommand {
  id?: string;
  status?: EntityStatus;
  updatedAt?: string;
  limit?: number;
  keyword?: string;
}

interface TrackRunPage {
  ok: boolean;
  runs: TrackRun[];
  message: string;
}

type TrackRunList = TrackRunPage;

const DEFAULT_STATUS: EntityStatus = 'active';
const DEFAULT_LIMIT: number = 20;
const MAX_LIMIT: number = 100;

function isValidStatus(value: unknown): value is EntityStatus {
  return value === 'draft' || value === 'active' || value === 'published' || value === 'archived';
}

function normalizeText(value: unknown): string {
  if (typeof value !== 'string') {
    return '';
  }
  return value.trim().toLowerCase();
}

function pad(value: number, width: number): string {
  let out: string = String(Math.floor(Math.abs(value)));
  while (out.length < width) {
    out = '0' + out;
  }
  return out;
}

function dateStamp(date: Date): string {
  return (
    pad(date.getUTCFullYear(), 4) +
    '-' +
    pad(date.getUTCMonth() + 1, 2) +
    '-' +
    pad(date.getUTCDate(), 2)
  );
}

function timeStamp(date: Date): string {
  return (
    pad(date.getUTCHours(), 2) +
    pad(date.getUTCMinutes(), 2) +
    pad(date.getUTCSeconds(), 2)
  );
}

function isoFromTimestamp(ms: number): string {
  const d: Date = new Date(ms);
  return dateStamp(d) + 'T' + timeStamp(d) + 'Z';
}

function parseIso(value: unknown): number {
  if (typeof value !== 'string' || value.length === 0) {
    return 0;
  }
  const ms: number = Date.parse(value);
  if (Number.isNaN(ms)) {
    return 0;
  }
  return ms;
}

function hashText(value: string): number {
  let h: number = 2166136261;
  for (let i = 0; i < value.length; i += 1) {
    h = h ^ value.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function determineBaseMs(command: TrackCommand): number {
  const explicit: number = parseIso(command.updatedAt);
  if (explicit > 0) {
    return explicit;
  }
  const seed: string =
    normalizeText(command.id) + '|' + normalizeText(command.keyword) + '|track';
  const base: number = Date.UTC(2024, 0, 1, 0, 0, 0);
  return base + (hashText(seed) % 100000) * 1000;
}

function buildRunId(seed: string, index: number): string {
  const h: number = hashText(seed + '#' + String(index));
  const part: string = pad(h % 100000000, 8);
  return 'run-' + dateStamp(new Date(0)) + '-' + String(index + 1) + '-' + part;
}

function buildCardId(seed: string): string {
  const h: number = hashText(seed + ':card');
  return 'card-' + pad(h % 1000000000, 9);
}

function normalizeLimit(limit: number | undefined): number {
  if (typeof limit !== 'number' || Number.isNaN(limit) || !Number.isFinite(limit)) {
    return DEFAULT_LIMIT;
  }
  const floored: number = Math.floor(limit);
  if (floored < 1) {
    return DEFAULT_LIMIT;
  }
  if (floored > MAX_LIMIT) {
    return MAX_LIMIT;
  }
  return floored;
