type UpdateRun = {
  id: string;
  status: string;
  updatedAt: string;
  command: string;
};

type UpdateCommand = {
  id: string;
  entity: string;
  fields?: Record<string, unknown>;
};

type Customer = {
  id: string;
  status: string;
  updatedAt: string;
  name: string;
  postcode: string;
};

const runStore: UpdateRun[] = [];

/**
 * Deterministically derive a stable timestamp-like value from a seed string.
 *
 * @param seed - The deterministic seed string.
 * @returns A stable numeric value derived from the seed.
 */
function deriveStamp(seed: string): number {
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % 1000000007;
  }
  return hash;
}

/**
 * Format a derived numeric stamp as a deterministic ISO-like datetime string.
 *
 * @param seed - The deterministic seed string.
 * @returns A stable datetime string derived from the seed.
 */
function deriveDatetime(seed: string): string {
  const stamp = deriveStamp(seed);
  const seconds = stamp % 86400;
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;
  const pad = (value: number): string => (value < 10 ? '0' + String(value) : String(value));
  return '2024-01-01T' + pad(hours) + ':' + pad(minutes) + ':' + pad(secs) + 'Z';
}

/**
 * Derive a deterministic ULID-like identifier from a seed string.
 *
 * @param seed - The deterministic seed string.
 * @returns A stable identifier string derived from the seed.
 */
function deriveId(seed: string): string {
  const alphabet = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  let hash = deriveStamp(seed);
  let out = '';
  for (let i = 0; i < 26; i += 1) {
    out = alphabet.charAt(hash % alphabet.length) + out;
    hash = Math.floor(hash / alphabet.length) + 7;
  }
  return out;
}

/**
 * Run an update command and return the resulting Customer record.
 *
 * @param command - The update command describing entity and fields.
 * @returns A promise resolving to the updated Customer record.
 */
// req-1
async function runUpdate(command: UpdateCommand): Promise<Customer> {
  const seed = command.id + ':' + command.entity;
  const updatedAt = deriveDatetime(seed);
  const customer: Customer = {
    id: deriveId(seed),
    status: 'updated',
    updatedAt: updatedAt,
    name: command.entity,
    postcode: typeof command.fields?.postcode === 'string' ? command.fields.postcode : '',
  };
  const record: UpdateRun = {
    id: customer.id,
    status: customer.status,
    updatedAt: updatedAt,
    command: command.entity,
  };
  runStore.push(record);
