}

/**
 * Validate a delivery date, requiring it to be strictly in the future relative to `now`.
 *
 * @param date - the requested delivery date.
 * @param now - the current date/time used as the comparison baseline.
 * @returns a validation result with a date-field error when the date is today or in the past.
 */
// req-9
function validateDeliveryDate(date: Date, now: Date): ValidationResult {
  const errors: Record<string, string> = {};
  if (!(date instanceof Date) || isNaN(date.getTime())) {
    errors.deliveryDate = "A valid delivery date is required.";
  } else if (!(now instanceof Date) || isNaN(now.getTime())) {
    errors.deliveryDate = "A valid current time is required to validate the delivery date.";
  } else {
    const dayMs: number = 24 * 60 * 60 * 1000;
    const dateStart: number = Math.floor(date.getTime() / dayMs);
    const nowStart: number = Math.floor(now.getTime() / dayMs);
    if (dateStart <= nowStart) {
      errors.deliveryDate = "Delivery date must be in the future.";
    }
  }
  const ok: boolean = Object.keys(errors).length === 0;
  const result: ValidationResult = { ok: ok, errors: errors };
  if (!ok) {
    result.message = "Delivery date is not in the future.";
  }
  return result;
}

