  if (recipientName.length === 0) {
    errors.recipientName = "Recipient name is required.";
  }

  const budgetRange: string = typeof input.budgetRange === "string" ? input.budgetRange.trim() : "";
  if (budgetRange.length === 0) {
    errors.budgetRange = "Budget range is required.";
  }

  const occasion: string = typeof input.occasion === "string" ? input.occasion.trim() : "";
  if (occasion.length === 0) {
    errors.occasion = "Occasion is required.";
  }

  const postcode: string = typeof input.deliveryPostcode === "string" ? input.deliveryPostcode.trim() : "";
